fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    let n = list.len();
    // Create a new vector to hold the result
    let mut new_list = Vec::with_capacity(n - 1);
    
    // Add elements before the k-th element (1-based index)
    for i in 0..(k - 1) {
        new_list.push(list[i]);
    }
    
    // Add elements after the k-th element
    for i in k..n {
        new_list.push(list[i]);
    }
    
    new_list
}